68	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
69	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
70	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
71	  static const std::pair<std::string, std::string> interesting[] = {
72	      {"RT_FIXTURES", "asm"},
73	      {"RT_C_FIXTURES", "c"},
74	      {"RT_C_V_FIXTURES", "c+rvv"},
75	      {"PROBE_V_FIXTURES", "probe"},
76	  };
77	  std::vector<Fixture> rows;
78	  std::set<std::string> seen;
79	
80	  for (size_t k = 0; k < lines.size(); ++k) {
81	    std::string var, body;
82	    if (!parse_assignment(lines[k], var, body)) continue;
83	    std::string family;
84	    for (const auto& it : interesting)
85	      if (it.first == var) { family = it.second; break; }
86	    if (family.empty()) continue;
87	
88	    // Splice continuation lines: a trailing backslash + newline becomes a space.
89	    size_t li = k;
90	    while (!body.empty() && body.back() == '\\') {
91	      body.pop_back();
92	      body.push_back(' ');
93	      if (++li < lines.size()) body += lines[li];
94	      else break;
95	    }
96	
97	    std::istringstream iss(body);
98	    std::string name;
99	    while (iss >> name)
100	      if (seen.insert(name).second) rows.push_back({name, family});
101	  }
102	
103	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
104	  if (seen.insert("handoff_roundtrip").second)
105	    rows.push_back({"handoff_roundtrip", "asm"});
106	
107	  return rows;
108	}
