171	int cmd_list(const Cli& cli) {
172	  // `fixtures` lists internal test ELFs -- a developer target, gated behind
173	  // ANDESIM_DEV so the release product offers only user-facing models/engines.
174	  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
175	  if (cli.positional.empty()) {
176	    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
177	    return 2;
178	  }
179	  const std::string& t = cli.positional[0];
180	  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
181	  if (t == "models") return list_models();
182	  if (t == "engines") return list_engines();
183	  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
184	               t.c_str(), targets);
185	  return 2;
186	}
